package com.fooddelivery.user;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import com.fooddelivery.user.entity.User;import com.fooddelivery.user.repository.UserRepository;@Configuration public class DataInitializer{@Bean CommandLineRunner seed(UserRepository r){return args->{if(r.count()==0){User u=new User();u.setName("Demo Customer");u.setEmail("demo@example.com");u.setPhone("555-0100");r.save(u);}};}}
